import sys,json,pathlib,os,datetime,hashlib,traceback
files=json.loads(sys.argv[1]); root=pathlib.Path(".").resolve()
print(json.dumps({"actual_writer_pid":os.getpid(),"started_utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"intended_files":len(files),"cwd":str(root)}),flush=True)
for name,body in files.items():
 p=root/name; b=body.encode()
 try:
  if p.exists():
   assert p.read_bytes()==b,"unexpected existing partial/source: "+name
  else:
   with p.open("xb") as f:
    f.write(b); f.flush(); os.fsync(f.fileno())
  print(json.dumps({"saved":name,"bytes":len(b),"sha256":hashlib.sha256(b).hexdigest()}),flush=True)
 except BaseException:
  print(json.dumps({"failed":name,"existing_bytes":p.stat().st_size if p.exists() else None,"utc":datetime.datetime.now(datetime.timezone.utc).isoformat()}),flush=True)
  raise
